// Frozen state version 1 schema (docs/spec/playthrough-state.md, state
// versions and migration; tactical-combat-handoff package "State versions and
// compatibility").
//
// This is a frozen contract: it never changes once released. It is a copy of
// `src/engine/state.ts` as it existed before the tactical state v2 work. Later
// work moves the live schema to v2 and keeps reading v1 documents through this
// module for migration and legacy rendering. Do not edit this file except to
// fix a proven divergence from the pre-v2 `state.ts` (with a test).
//
// Stored Playthrough state document (docs/spec/playthrough-state.md,
// stored-and-derived-state table; docs/spec/architecture.md, engine contract).
//
// The document carries a `stateVersion`, is validated with Zod when read, and
// refers to Scenario content only by ID.

import { z } from 'zod';

/** The frozen v1 state version. */
export const STATE_VERSION_V1 = 1 as const;

const attributesV1Schema = z.strictObject({
  might: z.number().int().min(0).max(3),
  agility: z.number().int().min(0).max(3),
  wits: z.number().int().min(0).max(3),
  presence: z.number().int().min(0).max(3),
});

export type BaseAttributesV1 = z.infer<typeof attributesV1Schema>;

const takenOnceChoiceV1Schema = z.strictObject({
  sceneId: z.string(),
  choiceId: z.string(),
});

const activeCombatV1Schema = z.strictObject({
  encounterId: z.string(),
  range: z.enum(['near', 'far']),
  round: z.number().int().min(1),
});

/** The frozen v1 Playthrough state document. */
export const PlaythroughStateV1Schema = z.strictObject({
  stateVersion: z.literal(STATE_VERSION_V1),
  scenarioId: z.string(),
  scenarioVersion: z.string(),
  contentHash: z.string(),
  status: z.enum(['active', 'ended']),
  endingId: z.string().optional(),
  step: z.number().int().min(0),
  character: z.strictObject({
    templateId: z.string(),
    name: z.string(),
    baseAttributes: attributesV1Schema,
    health: z.number().int().min(0).max(12),
  }),
  inventory: z.record(z.string(), z.number().int().min(1)),
  equipment: z.strictObject({
    weapon: z.string().optional(),
    outfit: z.string().optional(),
    talisman: z.string().optional(),
  }),
  currentLocationId: z.string(),
  activeSceneId: z.string().nullable().optional(),
  activeCombat: activeCombatV1Schema.nullable().optional(),
  visited: z.array(z.string()),
  revealed: z.array(z.string()),
  firedScenes: z.array(z.string()),
  takenOnceChoices: z.array(takenOnceChoiceV1Schema),
  flags: z.array(z.string()),
  encounterDamage: z.record(z.string(), z.number().int().min(0)),
});

export type PlaythroughStateV1 = z.infer<typeof PlaythroughStateV1Schema>;

export function parsePlaythroughStateV1(value: unknown): PlaythroughStateV1 {
  return PlaythroughStateV1Schema.parse(value);
}
